import React, { useState } from "react";
import axios from "axios";
import { useNavigate, Link } from "react-router-dom";
import './signup1.css'; // Import CSS for styling (optional)

function Signup1() {
    const history = useNavigate();

    // State variables for form inputs
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [name, setName] = useState('');
    const [age, setAge] = useState('');
    const [gender, setGender] = useState('');
    const [dob, setDob] = useState('');
    const [accountType, setAccountType] = useState('');
    const [parentName, setParentName] = useState('');
    const [motherName, setMotherName] = useState('');
    const [balance, setBalance] = useState('');

    async function submit(e) {
        e.preventDefault();

        try {
            const response = await axios.post("http://localhost:8003/signup1", {
                email,
                password,
                name,
                age,
                gender,
                dob,
                accountType,
                parentName,
                motherName,
                balance
            });

            if (response.data === "exist") {
                alert("User already exists");
            } else if (response.data === "notexist") {
                history("/home", { state: { id: email } });
            }
        } catch (error) {
            console.log(error);
            alert("An error occurred while signing up");
        }
    }

    return (
        <div className="signup">
            <h1>Signup</h1>
            <form onSubmit={submit}>
                <input type="text" onChange={(e) => setName(e.target.value)} placeholder="Name" required />
                <input type="number" onChange={(e) => setAge(e.target.value)} placeholder="Age" required />
                <select onChange={(e) => setGender(e.target.value)} required>
                    <option value="" disabled selected>Select Gender</option>
                    <option value="Male">Male</option>
                    <option value="Female">Female</option>
                    <option value="Other">Other</option>
                </select>
                <input type="date" onChange={(e) => setDob(e.target.value)} required />
                <select onChange={(e) => setAccountType(e.target.value)} required>
                    <option value="" disabled selected>Select Account Type</option>
                    <option value="Savings">Savings</option>
                    <option value="Checking">Checking</option>
                    <option value="Business">Business</option>
                </select>
                <input type="text" onChange={(e) => setParentName(e.target.value)} placeholder="Parent's Name" required />
                <input type="text" onChange={(e) => setMotherName(e.target.value)} placeholder="Mother's Name" required />
                <input type="number" onChange={(e) => setBalance(e.target.value)} placeholder="Balance Amount" required />

                <input type="email" onChange={(e) => setEmail(e.target.value)} placeholder="Email" required />
                <input type="password" onChange={(e) => setPassword(e.target.value)} placeholder="Password" required />
                <input type="submit" value="Sign Up" />
            </form>

            <br />
            <p>OR</p>
            <br />
            <Link to="/">Login Page</Link>
        </div>
    );
}

export default Signup1;
